import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Troubleshooting a Cephadm Deployment - Michel Raabe, B1 Systems GmbH","description":"","frontmatter":{"title":"Troubleshooting a Cephadm Deployment - Michel Raabe, B1 Systems GmbH","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Cephadm","故障排除","分布式存储","Ceph","云解决方案"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Troubleshooting_a_Cephadm_Deployment_-_Michel_Raabe_B1_Systems_GmbH.md","filePath":"posts/2023/Troubleshooting_a_Cephadm_Deployment_-_Michel_Raabe_B1_Systems_GmbH.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Troubleshooting_a_Cephadm_Deployment_-_Michel_Raabe_B1_Systems_GmbH.md"};function h(r,a,s,n,d,p){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-cephadm部署故障排除" tabindex="-1">会议主题：Cephadm部署故障排除 <a class="header-anchor" href="#会议主题-cephadm部署故障排除" aria-label="Permalink to &quot;会议主题：Cephadm部署故障排除&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主讲人-michael-raabe" tabindex="-1">主讲人：Michael Raabe <a class="header-anchor" href="#主讲人-michael-raabe" aria-label="Permalink to &quot;主讲人：Michael Raabe&quot;">​</a></h4><h4 id="主讲人简介" tabindex="-1">主讲人简介： <a class="header-anchor" href="#主讲人简介" aria-label="Permalink to &quot;主讲人简介：&quot;">​</a></h4><ul><li>职位：云解决方案架构师</li><li>公司：B1 Systems（德国公司，位于Ingelstadt，拥有140名员工）</li><li>业务范围：提供咨询、培训和支持服务，专注于开源产品，如Ceph和OpenStack</li></ul><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Cephadm部署概述</strong></p><ul><li>Cephadm是一个自动化部署工具，相较于手动部署，效率更高。</li><li>Cephadm的最新版本支持更多功能，如集群部署和NFS。</li><li>会议主要关注如何从集群中获取日志文件和监控部署，而不是讨论容器化安装的优缺点。</li></ul></li><li><p><strong>故障排除挑战</strong></p><ul><li>虽然Cephadm的部署过程自动化程度高，但缺乏详细的默认输出，使得故障排除变得困难。</li><li>有用户在遇到无法解决的错误时，会选择重新部署整个集群作为解决方案。</li></ul></li><li><p><strong>日志和监控方法</strong></p><ul><li>介绍了多种从Ceph集群中收集数据的方法，包括使用Ceph工具、Cephadm工具和日志文件。</li><li>强调了设置适当的日志级别的重要性，建议至少设置为5以获取更多详细信息。</li></ul></li><li><p><strong>工具和技巧</strong></p><ul><li>推荐使用Snoopy和Audit工具来监控和记录命令执行情况。</li><li>讨论了如何通过手动拉取和启动容器来验证问题，并检查日志文件。</li></ul></li><li><p><strong>最佳实践和建议</strong></p><ul><li>强调了正确配置Python、容器、网络和DNS的重要性。</li><li>建议避免使用Ansible与Cephadm冲突，坚持使用Cephadm以避免问题。</li><li>分享了一个客户从Ceph Storage版本4升级到5的案例，强调了自动化和手动配置的平衡。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了Cephadm在自动化部署方面的优势和挑战。</li><li>确定了多种故障排除和监控的方法，特别是使用Snoopy和Audit工具。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化Cephadm的日志输出和监控功能。</li><li>探索更多自动化和手动配置的平衡方法，以提高部署和故障排除的效率。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>主讲人感谢大家的参与，并鼓励大家继续探索和优化Cephadm部署和故障排除的方法。</li></ul><h4 id="会议反馈" tabindex="-1">会议反馈： <a class="header-anchor" href="#会议反馈" aria-label="Permalink to &quot;会议反馈：&quot;">​</a></h4><ul><li>与会者对Cephadm的讨论表示赞赏，并期待未来更多的优化和改进。</li></ul><p>[会议结束]</p>',18)])])}const _=e(o,[["render",h]]);export{u as __pageData,_ as default};
